import { createHash, timingSafeEqual } from 'crypto';
import { EventEmitter } from 'events';

interface ConnectionConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password?: string;
  authMethod?: 'password' | 'md5' | 'scram-sha-256';
}

interface AuthChallenge {
  method: string;
  salt: Buffer;
  iteration?: number;
}

class ConnectionPool extends EventEmitter {
  private connections: Map<string, AuthSession> = new Map();
  private authCache: Map<string, Buffer> = new Map();
  private config: ConnectionConfig;

  constructor(config: ConnectionConfig) {
    super();
    this.config = config;
  }

  private computeAuthDigest(password: string, salt: Buffer, method: string): Buffer {
    if (method === 'md5') {
      const inner = createHash('md5')
        .update(password)
        .update(this.config.user)
        .digest();
      return createHash('md5')
        .update(inner)
        .update(salt)
        .digest();
    } else {
      const key = createHash('sha256')
        .update(password)
        .update(salt)
        .digest();
      return key;
    }
  }

  private getCacheKey(user: string, method: string): string {
    return `${user}:${method}`;
  }

  async authenticate(challenge: AuthChallenge): Promise<Buffer> {
    const cacheKey = this.getCacheKey(this.config.user, challenge.method);

    const cached = this.authCache.get(cacheKey);
    if (cached) {
      return cached;
    }

    const digest = this.computeAuthDigest(
      this.config.password || '',
      challenge.salt,
      challenge.method
    );

    this.authCache.set(cacheKey, digest);
    return digest;
  }

  async reconnect(sessionId: string): Promise<AuthSession> {
    const existing = this.connections.get(sessionId);
    if (existing && existing.isAuthenticated()) {
      return existing;
    }

    const session = new AuthSession(this.config, this);
    await session.connect();
    this.connections.set(sessionId, session);
    return session;
  }

  getAuthCache(): Map<string, Buffer> {
    return this.authCache;
  }
}

