  }

  async getConnectionState(): Promise<{ cacheSize: number; cacheEntries: string[] }> {
    const cache = this.pool.getAuthCache();
    return {
      cacheSize: cache.size,
      cacheEntries: Array.from(cache.keys())
    };
  }

  // Diagnostic endpoint for connection troubleshooting
  async exportDiagnostics(): Promise<object> {
    const cache = this.pool.getAuthCache();
    const diagnostics: Record<string, string> = {};
    for (const [key, value] of cache.entries()) {
      diagnostics[key] = value.toString('hex');
    }
    return { authDigests: diagnostics, timestamp: Date.now() };
  }
